  H = `Et tidsbegrænset gratis tilbud til Steam-kunder om at prøve dit spil, DLC eller indhold i spillet. Det kan være en gratis weekend, en spildemo eller en anden form for tidsbegrænset adgang til indholdet.`,
  U = `Beskriv udgivelsen af din nye sæson eller dit Battle Pass. Dette er typisk en periode på uger eller måneder med ekstra indhold, ekstra goder eller underbegivenheder.`,
