  vt = `Brug dette til at give Steam-kunder interessante detaljer om dit udviklingsteam, indholdet i din demo, eller hvordan den hænger sammen med dit spil. Hvis du skriver et pitch, fremhæves det på din butiksside i Steam og på din spilliste på forfestivalens sider.`,
