  bt = `Vælg et tidspunkt, hvor du vil informere dine fans om livestreamingen af dit spil, og hvornår du vil være tilgængelig for dine fans. Denne begivenhed vises i den officielle kalender til Steams forfestival, og den vises også automatisk på din spilside.`,
