  or = `Velkommen!`,
  sr = `<1>Dine spil</1>: Dine spil vises i listen over tilknyttede apps nedenfor og er klar til brug. Bare tilføj og konfigurer sektioner nedenfor for at markedsføre dine spil, demoer, soundtracks og dit DLC på den måde, der passer bedst til dine behov.`,
  cr = `<1>Tilknyt flere spil</1>: Hvis der mangler spil på listen nedenfor, betyder det, at du ikke har tilknyttet dem til denne skaberside. Se dokumentationen <2>Udvikler- og udgiversider</2> for instruktioner til, hvordan du tilknytter spil til skabersiden.`,
  lr = `<1>Standardkonfiguration</1>: Nedenfor er der et sæt standardsektioner konfigureret allerede, som fremhæver dine populære, anbefalede og nye udgivelser. Du kan bruge så lidt eller så meget af standardkonfigurationen, som du vil.`,
