  _r = `Vi kunne ikke genopbygge emnetaggene for dette udsalg fra butikken, så editoren kan ikke åbnes sikkert. Genindlæs siden for at prøve igen.`,
  vr = `%1$s emner fra listen med linkede emner kunne ikke indlæses fra butikken, sandsynligvis fordi de er blevet udelukket eller ikke længere er til salg. Taggene blev ikke genopbygget, så det er muligt, at de forsvinder fra sektionerne, som filtreres ud fra tags (du kan fortsætte med at arbejde som normalt, hvis de er udelukket osv.): %2$s. `,
