  Dr = `Du kan gøre begivenheden synlig forud for startdatoen, hvis du ønsker, at dine spillere ved, at din begivenhed er på vej, og samtidigt gøre det muligt for dem at tilmelde sig notifikationer.`,
  Or = `Du kan gøre meddelelsen synlig forud for startdatoen, hvis du ønsker, at dine spillere ved, at din begivenhed er på vej, og samtidigt gøre det muligt for dem at tilmelde sig notifikationer.`,
