  Ar = `Denne type begivenhed har som regel en slutdato.`,
  jr = `Vælg en slutdato, så Steam ved, hvornår din begivenhed skal vises som afsluttet. Dette vil gøre det muligt for Steam at prioritere visning af dine andre begivenheder, som er nyere og aktive lige nu.`,
