  Lr = `Indtast tider i din lokale tidszone. Disse tider bliver automatisk konverteret og vist til seere i deres lokale tid.`,
  Rr = `Automatiske påmindelser`,
  zr = `Når du indstiller en begivenhed til at starte i fremtiden OG gør den synlig for dine fans hurtigere, kan de melde sig til at få en påmindelse, når begivenheden starter. Steam sender automatisk en push-notifikation og/eller en e-mail til Steam-brugeren baseret på vedkommendes indstillinger.`,
