  Gr = `Tilknyt app-ID til denne begivenhed?`,
  Kr = `Tillader tilknytning af et app-ID til begivenheden. Dette gør, at butikskapslen automatisk fremhæves nederst i beskrivelsen af den viste begivenhed. Det sender oplysninger om appen til andre widgets, f.eks. broadcast- eller programwidgetten, efter behov.`,
