  si = `Vælg, hvilken gren du vil tilknytte denne begivenhed til, og den vil tilknytte denne begivenhed med det nuværende build til den pågældende gren. Du kan også fjerne tilknytningen fra en begivenhed til et build ved at vælge "Denne begivenhed skal ikke tilknyttes et build".`,
