  qi = `I HTML har linjeskift som regel ingen indflydelse, men i BBCode vises de som tomme liner. Hvis du har brugt tags såsom <p> eller <br>, så afkryds ikke dette felt. Hvis du som regel bruger blogsoftware, som automatisk tilføjer <br> til linjeskift, så bør du afkrydse dette felt.`,
