  Fs = `Begivenheder, som vises på Steam China, kan deaktiveres, så de ikke vises for globale brugere`,
  Is = `Begivenheden, der skal klones, har indhold på følgende sprog. Markér felterne for de sprog, du vil gemme i den klonede begivenhed.`,
  Ls = `I de fleste tilfælde er det ikke en god idé at klone eksisterende sprog.`,
  Rs = `Vælg alle`,
  zs = `Fravælg alle`,
  Bs = `FEJL: Ugyldigt emne`,
  Vs = `Gentagelse af baggrundsbillede`,
  Hs = `Størrelse på baggrundsbillede`,
  Us = `Indstillinger for farvegraduering`,
  Ws = `Ét stort billede, ingen gentagelse, fast størrelse (standard)`,
  Gs = `Gentag baggrunden horisontalt`,
  Ks = `Gentag baggrunden vertikalt`,
  qs = `Gentag baggrunden i alle retninger`,
  Js = `Ét billede, som sløres og dækker baggrunden`,
  Ys = `Farve på karruselpil`,
  Xs = `Hvis baggrundsfarven eller baggrundsbilledet har en meget lys farve, kan det være svært at se pilen. Brug denne indstilling til at tilsidesætte karruselpilenes hvide standardfarve.`,
  Zs = `Hvis baggrundsfarven eller baggrundsbilledet har en meget lys farve, kan det være svært at se pilen. Brug denne indstilling til at tilsidesætte den hvide og grå standardfarve i karrusellens brødkrummer. Dette vises primært for mindre skærme, deriblandt Steam Deck.`,
  Qs = `Indlæser oplysninger om demo`,
  $s = `Der er ingen udgivet demo at dele opslaget med`,
  ec = `Begivenheden skal gemmes, før den kan deles med din demo.`,
  tc = `Når din begivenhed/meddelelse offentliggøres, vises den på demoens biblioteksside. Dette giver mulighed for at kommunikere med brugere, der kun ejer demoen. `,
  nc = `Temabegivenheder: %1$s`,
  rc = `Halloween 2022`,
  ic = `Handler denne begivenhed om opdateringer til dit spil til halloween 2022? Hvis du tilføjer nye baner, skins, illustrationer eller andet indhold til dit spil til halloween, eller hvis du kører tidsbegrænsede begivenheder med særligt uhyggeligt indhold, uhyggelige udfordringer eller andre lignende aktiviteter, vil vi gerne høre om det. Vi overvejer forskellige muligheder for bedre at vise temabegivenheder for et større publikum, men først har vi brug for at vide mere om, hvilke slags aktiviteter udviklere kører i deres spil (hvis de kører nogen) i anledning af den særlige lejlighed. Klik på "til" nedenfor, hvis denne begivenhed handler om en opdatering til dit spil til halloween 2022.`,
  ac = `Halloweenbegivenheder`,
  oc = `Afholder du en begivenhed, eller tilføjer du indhold til halloween? Læs %1$s for at få mere at vide om, hvordan du deltager i Steam Scream med din halloweenbegivenhed i dit spil.`,
  sc = `Dokumentation om Steam Scream-halloweenbegivenheden`,
  cc = `Nyt DLC eller udvidelse til spillet`,
  lc = `Permanent udvidelse med halloweentema til dit spil.`,
  uc = `Annoncér en tidsbegrænset halloweenbegivenhed i dit spil, som giver spillere ekstra genstande, bonusser, fordele, belønninger, XP osv. Disse har et start- og et sluttidspunkt.`,
  dc = `Kategori til nomineringer til Steamprisen`,
  fc = `Vælg en bestemt kategori, som dine fans kan nominere dit spil i. De kan nominere spillet i kategorien direkte i begivenheden!`,
  pc = `De fleste kategorier til Steamprisen i år er til spil, som er udgivet i %1$s (efter nomineringerne til sidste års Steampris den %2$s). Eftersom dit spil blev udgivet før den dato, kan det kun nomineres i kategorien "Lavet med kærlighed".`,
  mc = `Se vores <1>dokumentation her</1> for flere oplysninger og for at downloade en assetpakke til Steamprisen med skabeloner til illustrationer til at bruge til markedsføring.`,
  hc = `Dette spil kan ikke nomineres i nogen Steampriskategorier. Kontakt <1>Steamworks Support</1>, hvis du mener, at det er en fejl.`,
  gc = `Bekræft, at du anerkender, at butikssiden er usynlig`,
  _c = `Butikssiden til app-ID %1$s er i øjeblikket ikke synlig. Hvis du offentliggør denne begivenhed, vil brugere kunne se, at spillet eksisterer. Hvis du vælger at udgive denne begivenhed alligevel, skal du tydeligt bekræfte det her.`,
