  ol = `Vis kun udsalgslogoet i cross promotion-sektioner`,
  sl = `Udsalgssiden og pointbutikken udelader logoet. Andre sider, som krydspromoverer dette udsalg, viser det stadig.`,
  cl = `Denne udsalgsside viser ikke logoet. Logoet vises kun på sider, som krydspromoverer dette udsalg.`,
  ll = `Butikskapsler`,
  ul = `Disse kapsler bruges til at fremhæve denne udsalgsside i butikken på steder, hvor der normalt fremhæves spil: I karrusellen "Udvalgt og anbefalet", i butikshubs og i indkøbskurven. Det er de samme kapsler, som der uploades til et spil i fanen "Grafiske elementer" på butikssiden, i samme størrelser.`,
  dl = `Du kan uploade dem alle sammen på én gang. Et billede bliver automatisk tildelt til en kapsel, når størrelsen matcher kapslen nøjagtigt. Alt andet skal du selv tildele, og du vil blive bedt om at beskære det. Du kan navngive billedfilerne, så de slutter med et sprognavn for at kategorisere dem som det pågældende sprog (f.eks. "main_capsule_french.jpg").`,
  fl = `Fokuser på brandingen af udsalget. Sørg for, at logoet tydeligt kan læses.`,
  pl = `Vises i anbefalingssektionerne og på de smallere fremhævningspladser i hele butikken.`,
  ml = `Disse er små, så logoet skal kunne læses selv i den mindste størrelse.`,
  hl = `Bruges til lister i hele butikken og i indkøbskurven.`,
  gl = `Designet til at gøre reklame for udsalget. Undgå at bruge citater, anmeldelsesscorer eller priser.`,
  _l = `Vises øverst på forsiden i karrusellen "Udvalgt og anbefalet".`,
  vl = `Et vertikalt asset, som er designet til at gøre reklame for udsalget. Undgå at bruge citater, anmeldelsesscorer eller priser.`,
  yl = `Kan vises øverst på forsiden under sæsonudsalg og på andre udsalgssider.`,
  bl = `Megabanner i bibliotek`,
