  Fl = `Tillader, at brugeren klikker på logoet på udsalgssiden for at komme til et andet sted i butikken, f.eks. forsiden.`,
  Il = `Indtast kun den del af adressen, som kommer efter butiksstartsiden, uden indledende skråstreg. Skriv f.eks. category/pins_pegs for at linke til https://store.steampowered.com/category/pins_pegs.`,
  Ll = `Dette skal være i forhold til startsiden i butikken, så udelad præfikset https://store.steampowered.com/. Skriv f.eks. category/pins_pegs i stedet for https://store.steampowered.com/category/pins_pegs.`,
