  tu = `Din konto er begrænset. Begrænsede konti kan ikke gemme begivenhedsindhold. Se https://help.steampowered.com/faqs/view/71D3-35C2-AD96-AA3A for flere oplysninger.`,
  nu = `Sektion er markeret som skjult. Viser forhåndsvisning af redigeringen af baggrundens gruppebillede`,
