  wu = `Kommasepareret fil (CSV)`,
  Tu = `eXtensible Markup Language (XML)`,
  Eu = `Dette opretter og downloader en CSV-fil med kommaseparerede værdier, som indeholder felter for alle de sprog, der understøttes af Steam, plus eventuel tekst, du har indtastet tidligere.`,
  Du = `Bemærk: I den fil, du importerer, kan du ekskludere sprog, som du ikke ønsker at ændre med importen.`,
  Ou = `Vælg dit foretrukne format for at downloade CSV:`,
  ku = `Hvis du klikker på følgende knap, downloades der en XML-fil pr. sprog med indhold. Der eksporteres altid en engelsk fil.`,
  Au = `Bemærk: Hvis du har flere sprog, får du måske en advarsel fra browseren om, at vi forsøger at downloade flere filer. Du kan roligt tillade dette. Det skyldes, at vi gemmer hvert sprog i sin egen XML-fil.`,
