  Lu = `Importer lokaliseringsfil(er)...`,
  Ru = `Importer...`,
  zu = `Vælg en eller flere filer til upload for at importere lokaliseret tekst til din titel, undertitel, resuméet og beskrivelsen. Vi bruger filtypenavnet til at vurdere, om filen er en XML- eller en CSV-import. Til XML bruger vi API-sprogkoden sidst i filnavnet inden udvidelsen til at fastlægge, hvilket sprog indholdet i XML-filen er. Start med at eksportere CSV- eller XML-filen for at sikre, at du bruger det rigtige format.`,
  Bu = `Lokalisteringsimport gennemført. Følgende sprog er blevet opdateret: %1$s`,
  Vu = `Lokalisteringsimport gennemført. Ingen ændringer blev foretaget.`,
  Hu = `Vi kunne ikke parse eller genkende CSV-filen.`,
  Uu = `Filtypen er ikke ".xml" eller ".csv". Filnavnet kunne ikke parses: %1$s`,
  Wu = `Filnavnet specificerer ikke API-sprogkoden. Det forventede filformat er <user name>_<language>.xml: %1$s`,
  Gu = `Der opstod en fejl ved parsing og anvendelse af XML-data: %1$s`,
  Ku = `Eksporter engelsk kladde til Crowdin, eller importer alle andre sprog fra Crowdin`,
  qu = `Eksportér til Crowdin`,
  Ju = `Vil du uploade den aktuelle engelske kladde til Crowdin og derved overskrive alle nuværende engelske strenge?`,
