  Zu = `Udsalgssiden er blevet gennemgået af Valve og har nu de følgende begrænsninger.`,
  Qu = `Udsalgssiden pæne URL kan ikke længere redigeres`,
  $u = `Den pæne URL bruges muligvis med fremhævning, og ændringer ville gøre linket ugyldigt.`,
  ed = `Der kan ikke længere tilføjes flere applikationer, pakker eller bundter til denne udsalgsside`,
  td = `Gennemgangen af udsalgssiden var for de inkluderede applikationer/pakker/bundter. Der kan ikke tilføjes mere. De kan flyttes, reorganiseres og fjernes.`,
  nd = `Det er ikke tilladt at foretage flere ændringer på udsalgssiden.`,
  rd = `(Kun Valve) Send automatisk opdateringer til Crowdin`,
  id = `Ikke sendt til Crowdin endnu`,
  ad = `Når dette er slået til, sendes ændringer i begivenheden til Crowdin til oversættelse, når ændringerne gemmes. Lad dette være slået fra, indtil teksten til begivenheden ligger fast og er klar til oversættelse. Hvis du skal lave mange ændringer over en periode, så slå det fra, indtil du er færdig, og slå det til igen bagefter.`,
  od = `Husk at klikke på Gem, når du har ændret indstillingen.`,
