  _d = `Indsæt et billede direkte i teksten. Billedet vises i tekststørrelse.`,
  vd = `Konverter til tekstlink`,
  yd = `Vis billede`,
  bd = `De følgende fejl for den aktuelle begivenhed forhindrer udgivelse af begivenheden. Ret dem, og prøv at udgive igen.`,
  xd = `Begivenhedens starttidspunkt er ikke angivet.`,
  Sd = `Begivenhedens starttidspunkt (%1$s) er i fortiden. Du skal enten ændre starttidspunktet til et tidspunkt i fremtiden eller sætte det til nu. Hvis det var muligt at udgive i fortiden, kunne brugere, som har besøgt din side for nylig, gå glip af begivenheder, da deres sidste besøg ville være efter begivenhedens starttidspunkt.`,
  Cd = `Begivenhedens starttidspunkt (%1$s) er for tidligt. Sæt det tidligst til %2$s.`,
  wd = `Begivenhedens sluttidspunkt er før starttidspunktet`,
  Td = `Manglende sluttidspunkt: Sluttidspunktet kræves for denne begivenhed, men mangler.`,
  Ed = `Det nuværende synlighedstidspunkt er efter begivenhedens starttidspunkt, hvilket forhindrer, at begivenheden bliver synlig, når den starter.`,
  Dd = `Beskrivelsen må maks. fylde 32.000 tegn. Beskrivelsen på %1$s er længere end 32.000 tegn.`,
  Od = `Begivenhedens titel eksisterer på %1$s, men der mangler en beskrivelse. Begge kræves for hvert sprog, som understøttes.`,
  kd = `Begivenhedens beskrivelse eksisterer på %1$s, men der mangler en titel. Begge kræves for hvert sprog, som understøttes.`,
  Ad = `Begivenheden har ikke en titel eller en beskrivelse på nogen sprog.`,
  jd = `Denne begivenhed står til at blive vist på Steam China, men mangler en titel og en beskrivelse på følgende sprog: %1$s`,
  Md = `Du kan ikke udgive en begivenhed med kategorien "Stor opdatering" uden også som minimum at have engelsksprogede nøgleillustrationer. Store opdateringer fremhæves på spillets oplysningsside i skrivebordsbiblioteket.`,
  Nd = `Du kan ikke udgive en begivenhed af typen "%1$s" uden som minimum at have en engelsk kapselillustration.`,
  Pd = `Du kan ikke udgive en begivenhed af typen "%1$s" uden som minimum at have en kapselillustration på forenklet kinesisk (Steam China)`,
  Fd = `Et udsalg kan kun have en enkelt fanesektion`,
  Id = `Butikssiden til dette spil er i øjeblikket ikke synlig. Du skal bekræfte dette under indstillingsfanen, før du udgiver.`,
  Ld = `Fanen %1$s mangler %2$s af %3$s obligatoriske felter.`,
  Rd = `De følgende er advarsler fra den aktuelle begivenhed, som kan tilsidesættes og ikke forhindrer udgivelse, men vi anbefaler dog, at du retter dem.`,
  zd = `Mangler enten begivenhedsbeskrivelse på engelsk og/eller et begivenhedsnavn på engelsk. Engelsk er det primære sprog eller fallback-sprog for mange Steam-brugere. Uden det vil begivenhedens synlighed for Steam-kunder være meget begrænset.`,
  Bd = `Illustration mangler. Begivenheder tillader brugerdefinerede illustrationer, som hjælper med at markedsføre begivenheden og gøre den mere fængende for Steam-kunder. Uden illustrationer bruger vi en kapsel fra spillet.`,
  Vd = `Illustration mangler. Begivenheder tillader brugerdefinerede illustrationer, som hjælper med at markedsføre begivenheden og gøre den mere fængende for Steam-kunder. Uden illustrationer bruger vi gruppens avatar.`,
  Hd = `Når begivenhedskategorien er angivet som "Anden", bliver synligheden af denne begivenhed markant reduceret. Steam bruger begivenhedskategorier til at hjælpe med at dirigere begivenheder til Steam-kunder. "Anden" er den kategori med mindst indflydelse og bliver vist for det mindste antal af brugere.`,
  Ud = `Undertitlen eksisterer i %1$s ud af %2$s sprog. Overvej at sikre, at hver oversættelse også har en oversat undertitel.`,
  Wd = `Sprogspecifikke illustrationer eksisterer i %1$s ud af %2$s sprog. Dette er i orden at ignorere, hvis illustrationen ikke har behov for lokalisering. For sprog uden illustrationer, bruges den illustration, som er valgt for engelsk.`,
  Gd = `Synlighedstidspunktet er blevet justeret til et tidspunkt i fortiden, så hvis du gemmer nu, bliver begivenheden synlig. Når først den er synlig, kan starttidspunktet ikke ændres, og begivenheden kan ikke skjules.`,
  Kd = `Der er uploadet fremhævningsbilleder til denne begivenhed, men fremhævningsflaget er slået fra. Dette skal aktiveres af Valve, for at banneret kan vises på butikssiden.`,
  qd = `Destinations-URL'en til logoet på udsalgssiden er ikke i forhold til butikkens startside, så kunder, der klikker på logoet, bliver sendt til en side, som er nede. Den skal ligne category/pins_pegs, ikke https://store.steampowered.com/category/pins_pegs.`,
  Jd = `Flere sektioner af denne type fundet`,
  Yd = `Denne udsalgsside indeholder mindst én anden sektion af samme type som denne. Denne sektion er kun beregnet til at blive brugt én gang på en udsalgsside. Er du sikker på, at du har brug for flere sektioner af denne type?`,
  Xd = `Udgivelsen er gennemført.`,
