  Cf = `Opret ny begivenhed eller meddelelse`,
  wf = `Kladder (skjulte, ikke udgivet)`,
  Tf = `Dette er en liste med begivenheder, som er blevet gemt, og du er stadigvæk i gang med at redigere dem. De er usynlige for kunder, og kun medlemmer af dit spils fællesskabshold kan se dem. Når de er klar, skal du udgive disse begivenheder, før Steam-kunder kan se dem.`,
  Ef = `Planlagte begivenheder (skjulte, udgivne)`,
  Df = `Dette er en liste med begivenheder, som er planlagt til automatisk at blive synlige på et angivet tidspunkt i fremtiden. Du kan fortsætte med at redigere disse begivenheder, hvis du har behov for at lave opdateringer.`,
