  um = `E-mailen har lokalisering uden tilsvarende markedsføringsillustrationer på %1$s.`,
  dm = `Forbereder e-mail`,
  fm = `Der er ændringer i denne begivenhed, som ikke er gemt. Gem begivenheden, før du forbereder den til afsendelse.`,
  pm = `E-mailen er klar til at blive sendt. Er du klar til at låse e-mailen, så der ikke foretages yderligere ændringer? Dette sender ikke e-mailen, men forbereder den blot til at blive sendt, når du er klar.`,
