  xh = `Vis udvalgte udgivere`,
  Sh = `Det er valgfrit at filtrere til en liste med udgivere eller appID'er. Hvis ingen af disse er angivet, sammenholder vi de ovenstående indstillinger med udgivere i Steamworks.`,
  Ch = `* Viser %1$s`,
  wh = `Vi bruger %1$s, da der ikke er nogen tekst i begivenhedsbeskrivelsen for %2$s, som er valgt i forhåndsvisningen.`,
  Th = `Oversigt over synlighed`,
  Eh = `Baseret på dine indstillinger bliver dine begivenheder eller meddelelser vist de følgende steder:`,
  Dh = `Standardsteder`,
  Oh = `Valgfrie steder`,
  kh = `Eksponeringer`,
  Ah = `Butik: På dit spils butiksside`,
  jh = `Denne begivenhed vises på dit spils butiksside i sektionen "Nyheder og begivenheder".`,
  Mh = `Antallet her afspejler det forventede antal besøgende på din butiksside i den periode, hvor begivenheden vises.`,
  Nh = `Butik: På siden "Opdateret for nylig"`,
  Ph = `Hvis du bruger en synlighedsrunde til opdateringer, når du har slået begivenheden op, vises begivenheden på siden "Opdateret for nylig" for spillere, som ejer dit spil eller har det på deres ønskeliste.`,
  Fh = `Antallet her angiver, hvor mange brugere der ejer dit spil eller har det på deres ønskeliste og kan se det på siden "Opdateret for nylig".`,
  Ih = `Nyheder: På dit spils nyhedsside`,
  Lh = `Denne begivenhed vises på listen med nyheder, der kan tilgås ved at klikke på "Relaterede nyheder" fra dit spils butiksside.`,
  Rh = `Antallet er forventet trafik på dit spils nyhedsside.`,
  zh = `Fællesskab: I dit spils fællesskabshub`,
  Bh = `Inkluderer spillets primære hubside samt nyhedsfanen og meddelelser, som er linket fra din butiksside.`,
  Vh = `Fællesskab: I venneaktivitetsfeedet for spillere, som følger dit spil`,
  Hh = `Denne begivenhed kan vises i aktivitetsfeedet for spillere, som følger dit spil.`,
  Uh = `Det viste tal er antallet af spillere, som følger dit spil.`,
  Wh = `I fremtiden:`,
  Gh = `Bibliotek: På startsiden i Steam-biblioteket (eventuelt)`,
  Kh = `Dine spillere kan se denne begivenhed øverst på startsiden i deres bibliotek, afhængigt af hvor mange andre spil en spiller ejer og hver meddelelse eller opdaterings relative prioritet.`,
  qh = `(afventer moderering)`,
  Jh = `Bibliotek: Fremhævningsbanner på dit spils biblioteksside`,
  Yh = `Hvis du uploader et fremhævningsbanner, kan din begivenhed/meddelelse vises under "Spil"-knappen på dit spils side i Steam-biblioteket.`,
  Xh = `Bibliotek: På dit spils side i spilleres Steam-bibliotek`,
  Zh = `Din begivenhed vises i aktivitetssektionen på dit spils side i dine spilleres Steam-bibliotek.`,
  Qh = `Baseret på antallet af spillere, der ejer dit spil og kan se det i deres Steam-bibliotek.`,
  $h = `På værkstedssiden`,
  eg = `Du kan også slå denne begivenhed/meddelelse op i Steam-værkstedet til dit spil. For at aktivere denne funktion skal du klikke på fanen "Indstillinger" og vælge "Slå også op i dit værksted?". Som standardindstilling vises begivenheder/meddelelser ikke i værkstedssektionen.`,
  tg = `Banner på Steam-produktside for udsalg`,
  ng = `Banner på Steam-produktside synligt fra %1$s indtil %2$s`,
  rg = `Du kan angive et udsalgsbanner under fanen "Udsalg", der tillader, at fremhævede spil kan henvise til udsalget ved at vise det angivne banner øverst på deres Steam-produktside. Dette hjælper Steam-kunder, som ser en bestemt spilrabat via en e-mail om spil fra deres ønskeliste, eller når de gennemser butikken for også at lære om den større udsalgsbegivenhed. Disse bannere er kun synlige, når din begivenhed begynder og frem til slutningen af begivenheden eller i to uger, afhængigt af hvad der kommer først. Start- og sluttidspunkter for begivenheder fremgår under fanen "Indstillinger".`,
  ig = `Notifikation: E-mail til spillere, der følger spillet, udvikleren eller udgiveren`,
  ag = `Dette inkluderer alle dem, der følger spillets tilknyttede udviklersider, udgiversider og franchisesider.`,
  og = `De følgende udvikler-, udgiver- eller franchiselinks har ikke en synlig skaberside. Hvis du opretter en, kan det hjælpe dine kunder med at se, hvad du tilbyder, og give dem mulighed for at læse mere om dine begivenheder og nye spiludgivelser: %1$s`,
  sg = `Nyheder: Spilleres personlige begivenhedskalender`,
  cg = `Denne begivenhed bliver vist på den brugerdefinerede nyhedshub for spillere, som enten har dit spil i deres bibliotek, på deres ønskeliste, eller som følger dit spil.`,
  lg = `Notifikation: Push-notifikationer til spillere, der har valgt det`,
  ug = `Antallet af spillere, som udtrykkeligt har tilvalgt at få en påmindelse om denne begivenhed (downloadet en ekstern kalendervisning eller valgt at følge denne begivenhed).`,
  dg = `spillere, der modtager en e-mail`,
  fg = `Estimeret antal e-mails, som vil inkludere denne begivenhed som en del af mailen. Vi opretter jævnligt en opdateringspakke med målrettede begivenheder for hver kunde. Dette afhænger af hver kundes indstillinger for e-mail- og kommunikationspræferencer.`,
  pg = `spillere, som modtager markedsføringsbeskeder`,
  mg = `Estimeret antal spillere, som vil se denne begivenhed i deres brugerdefinerede markedsføringsbesked i Steam-klienten. Dette er et pop op-vindue, som vises, når Steam-klienten startes på skrivebordet. Her vises relevante Steam-udsalg og interessante begivenhedsoplysninger.`,
  hg = `spillere, som ignorerede denne begivenhed`,
  gg = `Antallet af spillere, som udtrykkeligt har valgt at ignorere denne begivenhed.`,
  _g = `Kunne ikke indlæse begivenhed`,
  vg = `Se dokumentation`,
  yg = `Marketingbesked om stor opdatering – gennemgang`,
  bg = `Når begivenheden er færdig, og det ikke er nødvendigt med flere ændringer, skal du sende den ind til gennemgang for at bruge den i en marketingbesked. Du er velkommen til at udgive den store opdateringsbegivenhed, så snart den er klar. Gennemgang og godkendelse kan tage op til %1$s hverdage.`,
  xg = `Opret følgende sag for at starte gennemgangsprocessen.`,
  Sg = `Opret gennemgangssag`,
  Cg = `Sagen er blevet sendt ind. Gennemgå og opdater informationen <1>her</1>.`,
  wg = `Resumé`,
  Tg = `Gør synlig`,
  Eg = `Dette vil være synligt de fleste steder med det samme, når du udgiver.`,
  Dg = `Bemærk, at nye opslag bliver gennemgået af vores moderatorer i den rækkefølge, de opslås. Der kan være over en times forsinkelse, før nyheder eller begivenheder vises i Steam-biblioteket. Hvis du ændrer dine eksisterende opslag, bliver de sat bagerst i moderatorkøen.`,
  Og = `Eller erstat indholdet i en eksisterende begivenhed`,
  kg = `Usædvanligt. Giver dig mulighed for at klargøre opdateringer i en slags "kladdebegivenhed" og derefter erstatte en eksisterende udgivet begivenhed med indholdet i denne begivenhed. Denne begivenhed vil forsvinde og erstatter den valgte udgivne begivenhed. Begivenhedstypen og synlighedsindstillingerne for den valgte begivenhed opdateres ikke.`,
  Ag = `Denne begivenhed blev klonet fra: "%1$s"`,
  jg = `Erstat oprindelig begivenhed`,
  Mg = `Indholdet i denne begivenhed erstatter indholdet i den begivenhed, den oprindeligt blev klonet fra:`,
  Ng = `Bemærk: Den oprindelige begivenhed skal være udgivet og synlig. Vi kan ikke erstatte den, før den er offentligt synlig.`,
  Pg = `Denne handling er øjeblikkelig. Den nye begivenhed erstatter indholdet i målbegivenheden og vil være synlig for Steam-brugere med det samme. Den nuværende begivenhed forsvinder med denne handling.`,
  Fg = `Målbegivenhedens titel: %1$s`,
  Ig = `Målbegivenhed sidst opdateret: %1$s`,
  Lg = `Målbegivenhed sidst opdateret af: %1$s`,
  Rg = `Indlæser information om udgivet begivenhed`,
  zg = `Bekræft, at du har forstået handlingen`,
  Bg = `Vælg en nyligt udgivet og synlig begivenhed, som skal erstattes`,
