  Yg = `Tilladelse nægtet`,
  Xg = `Broadcasting`,
  Zg = `Steam-broadcasting`,
  Qg = `Tillad Steam-broadcastere at blive vist på begivenheds- og butikssiden?`,
  $g = `Liste over tilladte broadcastere`,
  e_ = `Disse broadcastere har tilladelse til at blive vist på din begivenheds- og butiksside, når de streamer dit spil under denne begivenhed.`,
  t_ = `Pre-roll`,
  n_ = `Forældet: VOD-pipeline er nu deaktiveret. Vi beholder den i tilfælde af, at vi skal bruge den gamle video. Denne video vil blive vist i broadcastafspilleren før almindelige programmer. VOD skal have offentlige tilladelser (adskilt fra udgivelsesstatussen).`,
  r_ = `Indtast app-ID for VOD her`,
