  M_ = `Fjern chat fra produkt- og begivenhedsside`,
  N_ = `Genstandsdrops`,
  P_ = `Slå genstandsdrops til for denne broadcast?`,
  F_ = `Udføres droppene manuelt?`,
  I_ = `Tid i minutter, før droppet kan modtages?`,
  L_ = `Valgfrit: Lav en Steam-begivenhed med detaljer om drops. Nyttigt til udsalgsbegivenheder, som ikke har en begivenhedsside.`,
  R_ = `Klankonto-ID`,
  z_ = `GID for klanbegivenhed`,
  B_ = `Afspil i bredt format`,
  V_ = `Når dette er aktiveret, fjernes venstre og højre kolonne i afspilleren. Dette er kun nyttigt, når der er en enkel streaming i begivenheden, og kolonnerne virker distraherende for oplevelsen.`,
  H_ = `Aktiver tilstanden "Bredt format"`,
  U_ = `Hvis det er aktiveret, vises der en knap til at vise/skjule chat. Når chatten vises, går den tilbage til den almindelige ikke-brede spillertilstand. Når chatten er lukket, går den tilbage til bred spillertilstand.`,
  W_ = `Aktiver vis/skjul chat`,
  G_ = `Vis annonceringer af giveawayvindere`,
  K_ = `Indtast giveaway-ID`,
  q_ = `Hvis der er en giveaway tilknyttet broadcasten, og vindere annonceres i broadcastchatten, så gør indstilling af et giveaway-GID, at chatbeskederne kan hentes, selvom chatten er lukket. Der ses kun efter annonceringer til visningsformål.`,
  J_ = `Broadcast-titel`,
  Y_ = `Vælg fra en liste af standardtitler, som skal vises over din broadcast på butikssiden, eller indtast en brugerdefineret titel.`,
  X_ = `Indtast titel`,
  Z_ = `Se dokumentation`,
  Q_ = `Illustration til broadcast`,
  $_ = `Indstillinger for broadcastillustrationer`,
  ev = `Vis højre og venstre banner i stedet for spilkapsel.`,
  tv = `Når dette er slået til, vises banneret i Steam-butikken i stedet for spilkapslerne. Dette er nyttigt, hvis banneret har mere relevant information om begivenheden end en bestemt appkapsel. Det er også nyttigt, hvis flere spil streamer over tid, og du kun vil vise et enkelt element for begivenheden.`,
  nv = `Liste over tilladte broadcastere`,
  rv = `Det angivne Steam-ID er ugyldigt. Det skal være en 64-bit numerisk værdi.`,
  iv = `Broadcastbaggrund`,
  av = `Baggrundsgraduering (indre farve)`,
  ov = `Baggrundsgraduering (ydre farve)`,
  sv = `Kunne ikke indlæse brugeroplysninger`,
  cv = `Valgfri indstilling, der gør det muligt at markere en streaming med et bestemt sprog for seerne. Nyttigt, hvis der er flere streaminger for begivenheden på forskellige sprog, så vi kan vælge den bedste standardstreaming til brugere baseret på deres sprog.`,
  lv = `Prioritet`,
  uv = `Angiver denne broadcasts prioritet i forhold til andre broadcasts. Højeste prioritet bliver valgt over lavere prioritet. Hvis flere broadcasts har samme prioritet, vælges en af dem tilfældigt.`,
