  mv = `Generelt (lav)`,
  hv = `Steamingindholdstype`,
  gv = `Beskriver, om indholdet streames live, eller om der streames en optagelse. Hvis det er en optagelse, angives der, om det er første gang, den sendes på platformen, eller om det er en genudsendelse.`,
