  Lv = `Send feedback`,
  Rv = `Rapportér dette emne`,
  zv = `Beskriv venligst, hvordan dette emne overtræder Steams servicebetingelser. Inkluder alle relevante oplysninger eller links. Indsendelse af denne rapport kan ikke fortrydes.`,
  Bv = `Tidsplan`,
  Vv = `Planlægningsværktøj`,
  Hv = `Lav en tidsplan/tidslinje, som vises på din begivenhedsside?`,
  Uv = `Tilføj post i tidsplan`,
