  qv = `Type`,
  Jv = `Formål`,
  Yv = `VS-kamp`,
  Xv = `Dette er en konkurrencepræget kamp mellem to eller flere personer/hold. Efter kampen kan du opdatere resultatet og inkludere oplysninger om vinderen.`,
  Zv = `Broadcast`,
  Qv = `Dette fortæller brugerne, at de kan se en livestreaming på Steam eller et andet sted i denne periode.`,
  $v = `Start spil`,
  ey = `Dette beder brugerne om at deltage i begivenheden nu ved at starte deres spil og spille med.`,
  ty = `I virkeligheden`,
  ny = `Bruges, når programdelen finder sted og er kun tilgængelig for folk, som er til stede under begivenheden. Kan ikke broadcastes direkte. Bemærk: Det er evt. bedst ikke at inkludere dette i programmet, da Steam-fans ikke vil kunne deltage.`,
  ry = `Starttidspunkt`,
  iy = `Angivet i minutter fra begyndelsen af begivenheden.`,
  ay = `Minutter`,
  oy = `Denne programpost er blevet ændret fra standardværdien. Er du sikker på, at du vil slette den? Denne handling kan ikke fortrydes.`,
  sy = `Nuværende serier`,
  cy = `En serie binder et sæt af relaterede begivenheder sammen med et fælles brandingbillede og farveskema. Dette er ikke påkrævet, for at begivenheder vises på programmet. For eksempel hovedscene eller kunstserie.`,
  ly = `Ingen serie angivet.`,
  uy = `Tilføj serie`,
  dy = `Tilføjer en ny serie for at gruppere begivenheder og samle dem på programmet under et brand.`,
  fy = `Slet serie`,
  py = `Er du sikker på, at du vil slette denne serie?`,
  my = `Serie uden mærkning %1$s`,
  hy = `Tilføj begivenheder specifikt til denne serie. De er kun gyldige, hvis de er udgivet, og start- og slutdato er indenfor den planlagte tidsramme og matcher typen for begivenheden, som er tilladt på programmet.`,
  gy = `Aftaler om udsalgsbegivenheder`,
  _y = `Før du kan bruge udsalgsværktøjerne, skal du erklære dig enig i følgende krav:`,
  vy = `Jeg er indforstået med, at udsalgssiden tydeligt skal angive gruppen eller individerne, der har arrangeret udsalget eller begivenheden.`,
  yy = `Jeg er indforstået med, at jeg ikke kan garantere deltagere en bestemt grad af synlighed på Steam, og at jeg ikke kan opkræve betaling for placering på siden.`,
  by = `Jeg er indforstået med, at Valve forbeholder sig retten til at ændre udsalgssiden, inklusive, men ikke begrænset til, synligheden på spil eller broadcasts på siden, eller tekst eller billeder, der beskriver begivenheden.`,
  xy = `Jeg er indforstået med, at Valve vælger, hvilke begivenheder der skal fremhæves i Steam-butikken, og at min begivenhed ikke nødvendigvis bliver fremhævet.`,
  Sy = `Jeg er indforstået med, at jeg kun må tilføje spil til udsalgssiden, hvis udvikleren eller udgiveren har givet mig tilladelse til det. Spiludviklerne vil se, at deres spil indgår i mit udsalg, så snart jeg tilføjer det til min side her.`,
  Cy = `Jeg accepterer alle reglerne, som er fastsat i %1$s`,
  wy = `Læs mere i %1$s om design og oprettelse af udsalgssider.`,
  Ty = `dokumentationen`,
  Ey = `Primær kontaktperson`,
  Dy = `Hvis spiludviklere, udgivere eller pressen har spørgsmål om denne begivenhed, hvem skal de så kontakte?`,
  Oy = `indtast navn`,
  ky = `indtast e-mailadresse`,
