  Ly = `Retningslinjer gennemgået og accepteret.`,
  Ry = `Oplys navnet og URL'en på denne begivenheds arrangør. Disse oplysninger vises i toppen af din udsalgsside. Oplysningerne er påkrævede og kan redigeres når som helst.`,
  zy = `Begivenhedsarrangører`,
  By = `Opdater begivenhedsarrangører`,
  Vy = `Indtast arrangørinfo`,
  Hy = `Indtast navnet på den organisation, som har arrangeret begivenheden. Linket kan være til arrangørens skaberside på Steam eller til en ekstern URL-adresse. Det engelske navn er påkrævet, men det er valgfrit at oversætte navnet.`,
  Uy = `Disse oplysninger vises på udsalgssiden på følgende måde:`,
