  Gy = `Arrangørens navn`,
  Ky = `URL`,
  qy = `Lokaliseret billedgruppe`,
  Jy = `Primært billede til gruppe af lokaliserede billeder`,
  Yy = `Dette billede bruges automatisk som fallback, hvis der ikke er en lokaliseret udgave på et sprog, som brugeren vælger. Det kan være et billede uden indbrændt tekst eller et fællessprog for dine kunder.`,
  Xy = `Hvis billedet indeholder tekst, kan du uploade de oversatte billeder her på de sprog, som Steam understøtter. Steam viser automatisk de relevante oversatte billeder for kunderne.`,
  Zy = `Upload billeder med navneendelsen fra Steams %1$s, så vi automatisk kan tildele dem til det rigtige sprog.`,
  Qy = `Web API-sprog`,
  $y = `Billeder`,
  eb = `Brug området nederst til at uploade nye billeder, som kan tilgås fra alle dine begivenheder. Du kan trække og slippe dem fra denne sektion eller klikke for at indsætte billeder i fuld størrelse eller miniaturestørrelse i dit indlæg.`,
