  $b = `Overskrider maks. filstørrelse på %1$s`,
  ex = `Endeligt billede`,
  tx = `Dette fjerner alle oversatte billeder af denne type. Du skal gemme begivenheden bagefter, før det træder i kraft. Er du sikker?`,
  nx = `[Sidst opdateret: %1$s]`,
  rx = `Understøttede sprog`,
  ix = `Yderligere sprog`,
  ax = `Velkommen til den åbne beta for Steam-begivenheder`,
  ox = `Se dokumentationen for nærmere oplysninger og advarsler om, hvordan dine begivenheder og meddelelser fungerer under betaen.`,
  sx = `Feedback: Har du en fejl, du gerne vil anmelde, en kommentar eller et spørgsmål, du gerne vil stille? Send en besked i %1$s, eller kontakt din lokale Steam-kontoadministrator.`,
  cx = `Steamworks-forummet`,
  lx = `Der kommer snart mere`,
  ux = `I den åbne beta er denne visning kun synlig for dig og dit hold. Steam-kunder vil fortsat se begivenheder og meddelelser i den nuværende visning.`,
  dx = `Tips og specifikationer`,
