  mx = `%1$s pixel (bredde) x %2$s pixel (højde)   %3$s`,
  hx = `Dimensioner`,
  gx = `Logoer og tekst bør være centreret og inden for de midterste 800 px`,
  _x = `Logo`,
  vx = `Du kan navngive dine billedfiler med sprognavnene til sidst for automatisk at kategorisere dem som det pågældende sprog (f.eks. "header_danish.jpg). %1$s for at få en liste over understøttede sprog.`,
  yx = `Lokalisering`,
  bx = `Upload flere filer ved at trække dem ind i feltet nedenfor eller ved at klikke på knappen "Vælg fil".`,
  xx = `Upload billeder`,
  Sx = `Administrer 1 billede`,
  Cx = `Administrer %1$s billeder`,
  wx = `Tilføj et rubrikbillede på oplysningssiden for at kommunikere temaet eller essensen af opdateringen eller meddelelsen. Bemærk: Det er vigtigt at downloade skabelonerne (linket er øverst på siden) for at sikre, at rubrikbilledet udformes korrekt til de forskellige steder, hvor det bruges.`,
  Tx = `Forhåndsvisning af oplysningssiden:`,
  Ex = `Forhåndsvisning af pop op-siden til begivenheden:`,
  Dx = `Dette billede vises i sidepanelet ved siden af broadcasten.`,
  Ox = `Vigtige begivenheder eller meddelelser kan inkludere et bannerbillede, som vises på din butiksside under en begivenhed. Billedet på banneret er separat fra andre steder i butikken. Disse bannere skal godkendes af Valve, så du skal snakke med din kontakt hos Valve, før du uploader.`,
  kx = `Planlæg at medtage en kort, fængende beskrivelse af begivenheden, som fremstår tydeligt på fremhævningsbanneret, så spillere hurtigt kan se, hvad der gør begivenheden interessant.`,
  Ax = `Du kan bruge hele billedområdet og inkludere din egen beskrivelse af opdateringen eller begivenheden i billedet.`,
  jx = `Dette er mobilversionen af ovenstående fremhævning i butikken og bruges, når en bruger ser fremhævningen på en smal skærm.`,
  Mx = `Billedet vises som baggrund på udsalgssiden. Du kan lave billedet som ét stort billede eller lave en flise og indstille et mønster, der gentages.`,
  Nx = `Kritisk indhold bør placeres indenfor midtpunktet 940 pixels i billedet. Illustrationen kan gå ud over den renskårne kant i siderne og ned ad siden efter behov. Det anbefales generelt at lade illustrationen udtone til en udfyldt farve i siderne og i bunden og derefter indstille baggrundsfarven, så den matcher. Sørg for, at billedet er mindre end 4 MB.`,
  Px = `Download alle skabeloner til udsalgssider (.psd-filer)`,
  Fx = `Baggrundsbilledet til udsalgssiden fungerer godt sammen logoet til udsalgssiden angivet nedenfor. Hvis de bruges sammen, flyder logoet ovenpå baggrunden.`,
  Ix = `Skabeloner`,
  Lx = `Dette billede lægges oven på baggrunden øverst på din side. Hvis du vil have billedet oversat, kan du e-maile en .psd-fil til din kontaktperson hos Valve.`,
  Rx = `Hvis der er et banner, vises det på butikssiden for alle spil, som er med i denne udsalgsbegivenhed. Banneret vises under hele udsalgsbegivenheden, i op til to uger. Bemærk: Dette banner skal godkendes af Valve før brug og kan ikke være animeret.`,
  zx = `Denne version vises kun, når sideopløsningen reduceres til visning på mobilenheder.`,
  Bx = `Du kan også opdatere dit megabanner i biblioteket med branding for din opdatering, meddelelse, sæson eller anden begivenhed. For at gøre dette skal du gå til fanen "Grafiske elementer" i butikssideadministratoren.`,
  Vx = `Design`,
  Hx = `Dimensioner`,
  Ux = `Anvendelse`,
  Wx = `Påkrævet`,
  Gx = `Valgfri`,
  Kx = `Dette billede bør primært indeholde illustrationer og branding, som repræsenterer din begivenhed, samt hvis du vil dele en kort besked. Steam inkluderer altid automatisk dit spils navn og ikon ved siden af billedet i nogle sammenhænge, men du kan overveje også at inkludere spillogoet på forsidebilleder, da dette billede bruges, når din begivenhed deles på sociale medier.`,
  qx = `Det vises på din butiksside under de seneste meddelelser, på lister med begivenheder og meddelelser og på oplysningssiden i biblioteket. Billedet bruges til at repræsentere begivenheden, når den deles på sociale medier. Det bruges til at linke til din begivenhed/meddelelse og kan vises sammen med indhold fra flere andre spil, så billedet bør være tydeligt og genkendeligt.`,
  Jx = `Dette billede indeholder som regel illustrationer, som repræsenterer udgiveren, udvikleren eller franchisen. Steam inkluderer automatisk dit avatarikon ved siden af billedet i visse sammenhænge.`,
  Yx = `Det vises på steder i Steam, hvor denne skaberside vises, og bruges til at repræsentere begivenheden, når den deles på sociale medier. Billedet skal være tydeligt og genkendeligt.`,
  Xx = `Bannerbillede til link til årets bedste på Steam-listerne`,
  Zx = `Vises på udsalgets sektioner til cross promotions, f.eks. på siden "Rabatter og begivenheder", i stedet for at vise udsalgssidens logo. Hvis logoet ikke behøver at blive oversat, skal du uploade det én gang på engelsk, så bruger alle sprog det.`,
  Qx = `Et logo, som gengives i den øverste del af udsalgssiden ovenpå baggrundsbilledet. Billedet skal indeholde logoet for begivenheden, datoer og en eventuel tagline og have en gennemsigtig baggrund.`,
  $x = `Se dokumentation`,
  eS = `Billedeksempel`,
  tS = `Upload billede`,
  nS = `Uploadede sprog`,
  rS = `Tildel et andet sprog til dette billede`,
