  lS = `Vælg fil`,
  uS = `Fjern billede fra liste`,
  dS = `Fjern dette billede fra begivenhedens titelillustration for lokaliseringssproget %1$s? Dette sletter ikke det underliggende billede. Det fjerner tilknytningen til begivenheden.`,
  fS = `Det røde rektangel på billedet indikerer den plads, som dit logo og eventuel tekst skal være indenfor. Delområdet vises i visse sammenhænge, f.eks. i forbindelse med begivenhedslister.`,
