  OS = `Rediger appmetadata`,
  kS = `Giver tilladelse til at uploade depoter, teste Steamworks-funktioner, definere pakker, præstationer, førertavler, slå byttekort op osv. Giver også adgang og betegnelse som administrator i Steam-fællesskabet til alle applikationer i gruppen.`,
  AS = `Udgiv appændringer på Steam`,
  jS = `Giver tilladelse til at udgive ændringer i din titel, som er foretaget i Tekniske værkøjer > Rediger Steamworks-indstillinger på Steamworks-udviklersiden.`,
