  WS = `Administrer CD-nøgler`,
  GS = `Rediger appmarkedsføringsdata`,
  KS = `Giver tilladelse til at redigere og udgive butikssidedata såsom spilbeskrivelse, markedsføringsbilleder og videoer. Inkluderer også adgang til markedsføringsværktøjer såsom synlighedsrunder.`,
  qS = `Rediger oversættelsesdata til butikken`,
  JS = `Giver tilladelse til at redigere alle data på indstillingsfaner i butikken med et eller flere felter til oversættelse, f.eks. produktbeskrivelse og grafiske elementer. Giver ikke tilladelse til at udgive eller adgang til markedsføringsværktøjer såsom synlighedsrunder. Bemærk: Dette er en delmængde af funktionaliteten "Rediger appmarkedsføringsdata".`,
  YS = `Økonomi-/værkstedssupport`,
