  PC = `Vis overlay med begivenhedstitel- og beskrivelse i rubrikken`,
  FC = `Pixelforskydning`,
  IC = `Pixelforskydning deaktiveret, da logoet til udsalgssiden er på plads. Logoet håndterer automatisk pixelforskydning.`,
  LC = `Hvor mange pixels indholdet på udsalgssiden skal flyttes ned for at give plads til titlen og datoerne i baggrundsbilledet. Det burde ikke være nødvendigt at justere dette yderligere, medmindre du prøver at opnå noget særligt.`,
  RC = `Standardværdien (og den maksimale værdi) her bør være %1$s`,
  zC = `Dette sikrer, at din salgsside fungerer korrekt, når den vises på Steam Deck eller tablets.`,
  BC = `(Kun Valve) Begræns denne side til app-ejere?`,
  VC = `Låser siden bag en abonnementskontrol. Ikke-ejere omdirigeres (f.eks. til en købsside).`,
  HC = `Påkrævede appID'er`,
