  tE = `Nulstil`,
  nE = `Baggrundsvideo`,
  rE = `Baggrundsvideo (WebM)`,
  iE = `Baggrundsvideo (MP4)`,
  aE = `Anvendelse: Angiv begge URL'er for at vise en video oven på baggrundsbilledet. Hvert format kræves på forskellige platforme.`,
  oE = `Hvilken slags sektion skal dette være?`,
  sE = `Disse indstillinger styrer synligheden på landingssiden. Indstillingerne sender alle dataene i sektionen, så man vil kunne se dataene ved at inspicere hukommelsen. Med andre ord bliver dataene rent faktisk ikke skjult.`,
  cE = `Skjul altid denne sektion`,
  lE = `Skjul denne sektion inden et bestemt tidspunkt?`,
  uE = `Skjul denne sektion efter et bestemt tidspunkt?`,
  dE = `(brug din tidszone)`,
