  QI = `Vis knappen "Vis mere"`,
  $I = `Når dette er valgt, og hvis der er emner nok til at fylde det angivne antal af rækker, vises der en knap, så brugere kan se de resterende emner`,
  eL = `Vis knappen "Vis mere" på mobil`,
  tL = `Når dette er valgt, og brugeren er på mobil, og hvis der er nok emner til at fylde det angivne antal rækker, vises der en knap, så brugeren kan se resten af emnerne.`,
  nL = `Maks. emner`,
  rL = `Det maksimale antal emner, som kan vises efter tilfældig udvælgelse. Dette kan bruges, hvis du har et stort udvalg, men kun vil vise et begrænset antal. 0 betyder, at alt vises.`,
  iL = `Maks. antal rækker`,
  aL = `Denne sektion viser op til dette antal rækker, før knappen "Vis mere" bliver vist, så brugere kan se yderligere emner`,
