  sL = `Maks. synlige kapsler`,
  cL = `Kapsler, som altid skal inkluderes`,
  lL = `Ikke-udgivede titler som skal inkluderes`,
  uL = `Emner pr. række`,
  dL = `Antal emner, som vil blive vist i denne sektion. Et mindre antal gør, at visningerne er større, og et større antal gør, at der vises flere emner ad gangen. Nogle tillader et forskelligt antal pr. række, f.eks. viser 2/3/4 to emner på en række, 3 på den næste, så 4 og så tilbage til 3, 2.`,
  fL = `Ikke tilgængelig, når filterbaseret søgning er slået til.`,
  pL = `Karruselrækker`,
  mL = `Antallet af rækker, der vises i karrusellen. Dette reduceres eventuelt på små skærme eller på mobil.`,
  hL = `Dynamiske kapsler pr. række`,
  gL = `Varierer antallet af dynamiske kapsler pr. række for at give et mere visuelt interessant layout. Dette er eksperimentelt, og algoritmen vil formentlig blive ændret med tiden.`,
  _L = `Slå baggrund fra`,
  vL = `Rydder alle nuværende baggrundsindstillinger og fjerner margen rundt om udsalgssektionen. Dette bruges til tekst- eller billedsektioner, hvor man ikke ønsker margen.`,
  yL = `Brug denne stil på alle sektioner`,
  bL = `Kopierer denne sektions etiket- og baggrundsfarver, kant, øvre udfyldning, indstillingen "Slå baggrund fra" og baggrundsbilledet til alle andre sektioner på denne side. Tilsidesættelser af banner på produktsiden kopieres ikke.`,
  xL = `Dette erstatter baggrundsstilen for de %1$s andre sektioner på denne side med denne sektions stil. Du kan stadig fortryde dette ved ikke at gemme.`,
  SL = `Vis demooplysninger`,
  CL = `Vis muligheden om at installere en demo, hvis der er tilknyttet en demo til applikationerne i denne sektion. Det er muligt, at knappen ikke vises korrekt med alle skærmformater.`,
  wL = `Foretræk demoers selvstændige butikssider`,
  TL = `Når dette er slået til, og et spil har en demo med en selvstændig butiksside, fører linket til den selvstændige side i stedet for til grundspillets side.`,
  EL = `Vis overordnet applikation`,
  DL = `Gælder kun, når alle applikationer i denne sektion enten er DLC eller soundtracks. Dette viser grundspillet under DLC- eller soundtrackkapslen.`,
  OL = `Deaktiver sporing af duplikeringer`,
  kL = `Normalt vil apps, som vises højere oppe på siden, blive nedprioriteret længere nede, så populære apps ikke bliver duplikeret mange gange. Markér denne boks for at deaktivere sporing i denne sektion.`,
  AL = `Aktiver søgning`,
  jL = `Når dette er markeret, tilføjes der en søgefunktion til fanerne, så brugere kan søge efter emner ud fra navn`,
  ML = `Skjul priser`,
  NL = `Når dette er markeret, vises priserne på genstandskapsler ikke i denne sektion`,
  PL = `Vis Steam Deck-kompatibilitet (FORÆLDET)`,
  FL = `Hold musen over for at se dialogboksen med oplysninger om Steam Deck-kompatibilitet for dette spil`,
  IL = `Vis hardwarekompatibilitet`,
  LL = `Ved mouseover vises der en knap for hardwarekompatibilitet, og når du trykker på den, åbnes der en dialog med kompatibilitetsresultater for dette spil.`,
  RL = `Tillad knap til at skifte mellem udvidede/minimerede emner`,
  zL = `Viser en knap til at udvide/minimere emner, hvis emnerne i den aktive fane understøtter det.`,
  BL = `Åbn landingssiden for begivenheden direkte`,
  VL = `Når dette er markeret, skal brugere tages til landingssiden, når der klikkes på begivenheden. Når dette ikke er markeret, åbnes begivenheden i en indbygget modulbrowser, som i de fleste tilfælde er den bedste oplevelse, eftersom brugeren ikke behøver at forlade udsalssiden.`,
  HL = `Hvordan skal indholdet i denne sektion vises? Vælg en forudindstilling, eller konfigurer den manuelt.`,
  UL = `<1>Forudindstillede layouts</1>: Vælg en forudindstilling for hurtig konfiguration af denne sektion. Du kan altid bruge de manuelle indstillinger nedenfor til at finjustere eller helt ændre layoutet.`,
  WL = `Manuel konfiguration af layout`,
  GL = `Ét detaljeret emne`,
  KL = `Karrusel med 3 høje emner`,
  qL = `Karrusel med 4 emner`,
  JL = `Gitter af varierende størrelse`,
  YL = `Avancerede indstillinger`,
  XL = `Layoutvalg for emner`,
  ZL = `Indstillinger for emnelayout (kun tilgængelige for rækker med ét emne)`,
  QL = `Vælg emnets visningsstil. Dette ændrer emnets højde, det viste indhold og de mulige interaktioner direkte i kapslen.`,
  $L = `Disse indstillinger er kun tilgængelige, når indstillingen for emner pr. række er sat til 1.`,
  eR = `Almindelig kapselvisning`,
  tR = `Et almindeligt kapselelement med ekstra oplysninger: udgivelsesdato, platforme, op til 5 tags og en kort beskrivelse af spillet.`,
  nR = `Fuld kapselvisning`,
  rR = `Viser kapselemnet i fuld størrelse med rammens indhold samt anmeldelser og mulighed for at tilføje spillet til ønskelisten.`,
  iR = `Vertikal kapselvisning`,
  aR = `En højere visning af hvert emne, som bruger butikkens vertikale kapsel. Den indeholder de samme oplysninger som den fulde visning samt yderligere interaktioner, bl.a. mulighed for at se trailere og vælge imellem skærmbilleder. Visningen fungerer ikke for bundter, som i stedet automatisk bruger den fulde kapselvisning, og heller ikke for pakker, som automatisk bruger den primære apps biblioteksasset.`,
  oR = `Animeret vertikal kapselvisning`,
  sR = `En højere og bredere visning, som har en animeret overgang og viser mikrotraileren bag billedet. Visuelt flot, men det kan være distraherende med mere end én.`,
  cR = `Slank listekapsel`,
  lR = `Gør det muligt at oprette en tilpasset liste med spil ved at bruge en slank listevisning som i browseren til udsalgsemner.`,
  uR = `Kun køb`,
  dR = `Meget enkel visning beregnet til deluxe-pakker. Ingen kapselbilleder. Kun navn og købsknapper.`,
  fR = `Vis knap for købsmuligheder`,
  pR = `Når dette er markeret, erstattes knappen "Læg i kurv" med en knap, som viser alle købsmulighederne.`,
  mR = `Dynamisk visningssektion`,
  hR = `En dynamisk visningssektion er nyttig i forbindelse med en livestreaming. Den lader arrangøren tilføje applikationer/pakker/bundter, som er synlige i butikken, efter udsalget er synligt, og vise dem for Steam-kunder på siden, uden at de skal opdatere siden. Vi anbefaler at placere denne sektion nær broadcastafspilleren. Tilføj kun synlige applikationer, ellers cachelagrer butikssiden den skjulte tilstand, og applikationen vil så ikke være synlig for Steam-kunder.`,
  gR = `Skjul, hvis der er for få emner`,
  _R = `Hvis dette er markeret, skjules sektionen, hvis der er for få emner til at fylde en enkelt række.`,
  vR = `Skjul duplikerede begivenheder`,
  yR = `Hvis dette er markeret, bliver begivenheder fjernet fra denne sektion, hvis de allerede er blevet vist i en tidligere sektion. Virker bedst, hvis de forrige sektioner enten er sektioner til manuelt kuraterede begivenheder eller sektioner, som viser nyligt taggede begivenheder fra spil i brugerens ønskeliste, bibliotek eller anbefalinger.`,
  bR = `Den dynamiske visningssektion bruges sammen med livestreaminger. Vi anbefaler at placere denne sektion nær broadcastafspilleren på udsalgssiden. Den tjekker jævnligt, om der er blevet tilføjet nye Steam-begivenheder til listen, og viser dem, uden at kunden skal opdatere siden.`,
  xR = `Kun én dynamisk visningssektion er tilladt for applikationer/bundter/pakker og én for nyheder og begivenheder`,
  SR = `Funktion understøttes ikke for denne smartsektion`,
  CR = `Dynamisk visning kræver, at den særlige begivenhed er forbundet med en partnertilmelding. Konfigurer tilmeldingssiden i sektionen med generel konfiguration.`,
  wR = `Quiz`,
  TR = `Opret ét eller flere oversatte spørgsmål og svar. Hvert spørgsmål eller svar kan have en video tilknyttet.`,
