  kG = `Tillader direkte redigering i listen med linkede emner i dette udsalg. Dette kan bruges til at importere eller eksportere fra værktøjer såsom Excel eller til hurtigt at lave store ændringer i listen med emner.`,
  AG = `Brugerdefinerede etiketter`,
  jG = `Gør det muligt at redigere listen over linkede emner i dette udsalg samt importere og eksportere udelukkende den brugerdefinerede samling af etiketter på udsalgsemnerne. Dette bruges primært til at importere et udvalg af brugerdefinerede etiketter, som administreres via et eksternt regneark uden at ændre de andre etiketter på emnerne. Derudover kan en delmængde importeres via denne dialogboks, da det ikke vil fjerne emner, som ikke er på listen.`,
