  uq = `Nye emners synlighed`,
  dq = `Angiver, hvilken dag i udsalget de angivne emner bliver fremhævet. Som standard vises de på alle dage, men denne indstilling kan bruges til at begrænse emner til bestemte dage i udsalget`,
  fq = `Udsalgsbaggrunde pr. dag`,
  pq = `Standardværdien 1 betyder, at der bruges en enkelt rubrikbaggrund under hele udsalget. En højere værdi gør, at der kan vises forskellige illustrationer på forskellige dage. Illustrationen fra den foregående dag vises fortsat derefter. Det mulige antal baggrunde er baseret på antallet af dage i begivenheden, som er angivet i indstillingsfanen.`,
