  jq = `Ikke tilladt`,
  Mq = `Dette emne kan ikke tilføjes, fordi det ikke er tilknyttet udsalgssidens skaberside (udvikler, udgiver eller franchise). Tilknyt emnet, og genindlæs udsalgssiden for at opdatere tilknytningen.`,
  Nq = `Bundt ikke tilladt`,
  Pq = `Dette bundt kan ikke tilføjes, fordi det ikke er tilknyttet udsalgssidens skaberside (udvikler, udgiver eller franchise). Tilknyt emnet, og genindlæs udsalgssiden for at opdatere tilknytningen. Disse applikationer er ikke tilknyttet skabersiden: (%1$s)`,
  Fq = `Pakke ikke tilladt`,
  Iq = `Denne pakke kan ikke tilføjes, fordi den ikke er tilknyttet udsalgssidens skaberside (udvikler, udgiver eller franchise). Tilknyt emnet, og genindlæs udsalgssiden for at opdatere tilknytningen. Disse applikationer er ikke tilknyttet skabersiden: (%1$s)`,
  Lq = `Denne begivenhed blev klonet fra en tidligere begivenhed. Udsalgssidefunktionen skal aktiveres her af Valve, før du kan konfigurere denne udsalgsside.`,
