  $J = `Manuelt`,
  eY = `Navn på denne facetværdi. En facetværdi er en individuel indstilling, som brugeren kan klikke på for at filtrere de spil, der vises i denne sektion. For eksempel "førsteperson".`,
  tY = `Valgfri tekst, der vises til højre for facetværdien. Brug den til at give en kort forklaring af en facetværdi. For eksempel "1-2 timer" for en facetværdi, der gælder for spil med kort spilletid.`,
  nY = `Navn på denne facet. En facet er en gruppe af indstillinger, som brugeren kan klikke på for at filtrere de spil, der vises i denne sektion. For eksempel "genre".`,
  rY = `Udfylder automatisk facetterne og facetværdierne baseret på kategorier af butikstags, bl.a. "genre" og "visuelle elementer og perspektiv". Efter den automatiske udfyldning kan du manuelt redigere hver facet og facetværdi efter behov.`,
  iY = `Fjerner facetværdier, som ikke matcher nogen af emnerne i denne sektion.`,
  aY = `Hvad er det mindste antal resultater, der skal være i en valgt facet? Dette skjuler eventuelle søgeord fra menuen til venstre, som ikke har mindst dette antal matchende emner. Antallet beregnes, efter at eventuelle fanefiltre er blevet anvendt. Som regel er omkring 5 et godt antal.`,
  oY = `Viser højst dette antal indstillinger under en hovedkategori i menuen til venstre. For eksempel: Vis ikke flere end dette antal genrer under en facet, som hedder "genre". 5 er som regel godt.`,
  sY = `Sorterer facetværdier for hver facet ud fra denne parameter. Det bedste er som regel efter antal matches.`,
  cY = `Sorterer facetværdier inden for hver facet i alfabetisk navnerækkefølge.`,
  lY = `Sorterer facetværdier inden for hver facet i faldende rækkefølge blandt de emner, der matcher dem. For eksempel: Under en facet kaldet "genre" vises "rollespil" før "strategi", hvis der er flere rollespil end strategispil i denne sektion.`,
  uY = `Sorterer ikke facetværdier. De vises i den rækkefølge, der er angivet på listerne nedenfor.`,
  dY = `Fremhævet facetfarve`,
  fY = `Rubrikfarve`,
  pY = `Aktiveret som standard`,
  mY = `Synkroniser de 20 mest populære butikstags`,
  hY = `Som standard synkroniseres kun de 10 mest populære butikstags for hvert emne. Afkryds dette felt for i stedet at synkronisere de 20 mest populære butikstags.`,
  gY = `Generer information til fejlfinding`,
  _Y = `Logisk OG`,
  vY = `Hvis dette er markeret, når brugeren vælger flere facetværdier i denne facet, bruges logisk OG på de valgte facetværdier i filtret. Ellers bruges logisk ELLER på de valgte facetværdier i filtret.`,
  yY = `Udvidet til at begynde med`,
