  VY = `Tilføj virtuel genstand`,
  HY = `Du kan vælge at uploade for at tilsidesætte standardbilledet, som er knyttet til den virtuelle genstand. Ellers bruger vi det billede, der ville blive vist for den virtuelle genstand i genstandsbutikken.`,
  UY = `Indløs gratis genstand`,
  WY = `En sektion, hvor brugere kan indløse gratis genstande. Her afsløres det, når de kan indløse noget igen næste gang (hvis relevant). Kan bruges til daglige genstandsdrops. Knyttet til belønningswidgetten til konfigurering af indløsning af udsalgsgenstande.`,
